import threading

from sqlalchemy import text

from transactions.common import heading, make_engine, run_concurrently


def count_large_orders_twice(isolation_level: str) -> list[int]:
    engine = make_engine()
    with engine.begin() as connection:
        connection.execute(text("DROP TABLE IF EXISTS tx_demo_orders"))
        connection.execute(
            text(
                "CREATE TABLE tx_demo_orders ("
                "id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "
                "amount integer NOT NULL)"
            )
        )
        connection.execute(text("INSERT INTO tx_demo_orders (amount) VALUES (150)"))

    first_read_done = threading.Event()
    insert_committed = threading.Event()
    counts: list[int] = []

    def reader() -> None:
        with engine.connect().execution_options(
            isolation_level=isolation_level
        ) as connection:
            with connection.begin():
                counts.append(
                    connection.scalar(
                        text(
                            "SELECT count(*) FROM tx_demo_orders "
                            "WHERE amount >= 100"
                        )
                    )
                )
                first_read_done.set()
                if not insert_committed.wait(timeout=10):
                    raise TimeoutError("Writer did not commit")
                counts.append(
                    connection.scalar(
                        text(
                            "SELECT count(*) FROM tx_demo_orders "
                            "WHERE amount >= 100"
                        )
                    )
                )

    def writer() -> None:
        if not first_read_done.wait(timeout=10):
            raise TimeoutError("Reader did not perform its first SELECT")
        try:
            with engine.begin() as connection:
                connection.execute(
                    text("INSERT INTO tx_demo_orders (amount) VALUES (200)")
                )
        finally:
            insert_committed.set()

    run_concurrently(reader, writer)
    engine.dispose()
    return counts


def main() -> None:
    heading("Phantom read: large orders")
    read_committed = count_large_orders_twice("READ COMMITTED")
    repeatable_read = count_large_orders_twice("REPEATABLE READ")
    serializable = count_large_orders_twice("SERIALIZABLE")

    print(f"READ COMMITTED: {read_committed}")
    print(f"REPEATABLE READ: {repeatable_read}")
    print(f"SERIALIZABLE: {serializable}")
    assert read_committed == [1, 2]
    assert repeatable_read == [1, 1]
    assert serializable == [1, 1]
    print(
        "PASS: a phantom appears at READ COMMITTED; PostgreSQL prevents it "
        "at both REPEATABLE READ and SERIALIZABLE."
    )


if __name__ == "__main__":
    main()
